import{_ as t,o,c as a,ag as s}from"./chunks/framework.44aEvdQQ.js";const c=JSON.parse('{"title":"The Trap — Do, Own, Risk","description":"","frontmatter":{"title":"The Trap — Do, Own, Risk","order":2},"headers":[],"relativePath":"about/chapters/02-the-trap-do-own-risk.md","filePath":"about/chapters/02-the-trap-do-own-risk.md"}'),i={name:"about/chapters/02-the-trap-do-own-risk.md"};function n(r,e,l,h,d,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h3 id="the-trap-—-do-own-risk" tabindex="-1">The Trap — Do, Own, Risk <a class="header-anchor" href="#the-trap-—-do-own-risk" aria-label="Permalink to &quot;The Trap — Do, Own, Risk&quot;">​</a></h3><h4 id="how-owners-conflate-roles-and-cage-themselves" tabindex="-1">How Owners Conflate Roles and Cage Themselves <a class="header-anchor" href="#how-owners-conflate-roles-and-cage-themselves" aria-label="Permalink to &quot;How Owners Conflate Roles and Cage Themselves&quot;">​</a></h4><p>As an owner, you&#39;re divided in three distinct ways:</p><ul><li><strong>Do</strong>: The role you perform (new business, operations, delivery, whatever it may be). If you stepped away from the business, this would be the job description(s) you would write to hire a replacement(s)</li><li><strong>Own</strong>: Assets and liabilities. The part where you take profit distributions, or (hopefully not), when you need to put your own cash into the business to meet payroll</li><li><strong>Risk</strong>: Capital at stake. The initial seed money to start the business, the sweat equity that was never compensated, and the ongoing risk of doing business</li></ul><p>Practitioners inevitably become owners without differentiating these distinct roles. What starts as a freelance gig turns into a 10-person firm, seemingly overnight. Owners tend not to consider which role they&#39;re performing in any given conversation, to their detriment. The treadmill mindset — Pavlovian phone-checking, client PTSD, inability to step back — is what makes &quot;working on the business&quot; feel impossible. By facing the truth, that as an owener you&#39;re not always the &quot;savior,&quot; or the decision-maker, you&#39;re liberated to delegate responsibility to your people, elevating them to trusted allies.</p>',5)])])}const w=t(i,[["render",n]]);export{c as __pageData,w as default};
